package com.noop.mgecg;

// FILE VERSION 0.23.1 (28 Oct 2026): GENERATED. The analysis code (Python reference and the Java port) as a zip, base64 in pieces, so it travels with the app.
// "Save the analysis code" on the ECG tab writes it to Download/MGreports/MG_ECG_analysis_code.zip. Regenerate whenever the scripts or the Pro* classes change.

final class AnalysisCodeData {
    private AnalysisCodeData() {}
    private static final String[] PARTS = {
        "",
        "",
        "",
        "",
        ""
    };
    static byte[] bytes() {
        StringBuilder s = new StringBuilder();
        for (String p : PARTS) s.append(p);
        return java.util.Base64.getDecoder().decode(s.toString());
    }
}
